-- PostgreSQL format literals use unescaped double quotes. Backslashes became
-- serialized output in earlier local M7-04 migrations and broke Zod datetime.
create or replace function public.m7_snapshot_json(p_organization_id uuid,p_snapshot_id uuid)
returns jsonb language sql stable security definer set search_path=public,pg_temp as $$
  select jsonb_build_object('id',s.id,'organizationId',s.organization_id,'technicalFileId',s.technical_file_id,'productId',s.product_id,'technicalFileVersion',s.technical_file_version,'releaseId',s.release_id,'purpose',s.purpose,'auditRationale',s.audit_rationale,'templateKey',s.template_key,'templateVersion',s.template_version,'readinessStatus',s.readiness_status,'payload',s.payload,'payloadByteLength',s.payload_byte_length,'payloadSha256',s.payload_sha256,'status',s.status,'supersededBySnapshotId',s.superseded_by_snapshot_id,'createdByUserId',s.created_by,'createdAt',to_char(s.created_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')) from public.technical_file_snapshots s where s.organization_id=p_organization_id and s.id=p_snapshot_id
$$;

create or replace function public.m7_snapshot_export_json(p_organization_id uuid,p_export_id uuid)
returns jsonb language sql stable security definer set search_path=public,pg_temp as $$
 select jsonb_build_object('id',e.id,'snapshotId',e.snapshot_id,'status',e.status,'failureCode',case e.failure_code when 'object_write_failed' then 'storage_unavailable' when 'renderer_failed' then 'unknown' when 'cancelled' then null else e.failure_code end,'cancellationReason',e.cancellation_reason,'artifacts',case when e.status='ready' then jsonb_build_array(jsonb_build_object('kind','pdf','fileName','technical-file.pdf','mimeType','application/pdf','byteLength',e.pdf_bytes,'sha256',e.pdf_sha256,'generatedAt',to_char(e.completed_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')),jsonb_build_object('kind','archive','fileName','technical-file-archive.zip','mimeType','application/zip','byteLength',e.archive_bytes,'sha256',e.archive_sha256,'generatedAt',to_char(e.completed_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')),jsonb_build_object('kind','manifest','fileName','manifest.json','mimeType','application/json','byteLength',e.manifest_bytes,'sha256',e.manifest_sha256,'generatedAt',to_char(e.completed_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'))) else '[]'::jsonb end,'manifestSha256',case when e.status='ready' then e.manifest_sha256 else null end,'idempotencyKey',e.idempotency_key,'createdAt',to_char(e.created_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),'startedAt',case when e.started_at is null then null else to_char(e.started_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"') end,'completedAt',case when e.completed_at is null then null else to_char(e.completed_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"') end) from public.technical_file_snapshot_exports e where e.organization_id=p_organization_id and e.id=p_export_id
$$;

create or replace function public.m7_snapshot_timestamp_utc(p_value timestamptz)
returns text language sql immutable set search_path=public,pg_temp as $$
 select to_char(p_value at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')
$$;

create or replace function public.create_technical_file_snapshot_atomic(p_organization_id uuid,p_actor_user_id uuid,p_product_id uuid,p_expected_technical_file_version integer,p_purpose text,p_release_id uuid,p_audit_rationale text,p_idempotency_key uuid)
returns table(outcome text,result jsonb) language plpgsql security definer set search_path=public,pg_temp as $$
declare f public.technical_files%rowtype; r public.product_releases%rowtype; snapshot_id uuid; payload jsonb; payload_text text; digest text; replay record; readiness jsonb; retention jsonb; technical_file jsonb;
begin
 if p_purpose not in ('release','audit') or p_expected_technical_file_version < 1 or p_idempotency_key is null or not public.m7_technical_file_actor_can(p_organization_id,p_actor_user_id,'can_snapshot_technical_files') then return query select 'forbidden',null::jsonb; return; end if;
 perform pg_advisory_xact_lock(hashtextextended(p_organization_id::text||':'||p_actor_user_id::text||':'||p_idempotency_key::text,0)); select a.* into replay from public.audit_logs a where a.organization_id=p_organization_id and a.user_id=p_actor_user_id and a.changes->>'idempotencyKey'=p_idempotency_key::text order by a.created_at desc,a.id desc limit 1; if found then if replay.action='technical_file.snapshot_created' then return query select 'replayed',public.m7_snapshot_json(p_organization_id,(replay.changes->>'snapshotId')::uuid); else return query select 'idempotency_conflict',null::jsonb; end if; return; end if;
 lock table public.technical_file_sections,public.technical_file_section_sources,public.technical_file_section_source_reviews,public.technical_file_risk_registers,public.technical_file_risks,public.technical_file_risk_revisions,public.technical_file_risk_revision_assets,public.technical_file_risk_revision_requirements,public.technical_file_risk_revision_evidence in share mode;
 select * into f from public.technical_files where organization_id=p_organization_id and product_id=p_product_id and status='active' for update; if not found then return query select 'not_found',null::jsonb; return; end if; if f.version<>p_expected_technical_file_version then return query select 'conflict',jsonb_build_object('currentVersion',f.version); return; end if;
 if p_purpose='release' then select * into r from public.product_releases where organization_id=p_organization_id and product_id=p_product_id and id=p_release_id and archived_at is null and lifecycle='released' for share; if not found then return query select 'invalid_request',null::jsonb; return; end if; elsif p_release_id is not null or char_length(btrim(coalesce(p_audit_rationale,''))) not between 1 and 4000 then return query select 'invalid_request',null::jsonb; return; end if;
 select x.result->'technicalFile' into technical_file from public.get_technical_file(p_organization_id,p_actor_user_id,p_product_id) x where x.outcome='found'; if technical_file is null then return query select 'not_found',null::jsonb; return; end if; readiness:=public.m7_evidence_readiness_json(p_organization_id,p_product_id); select t.retention into retention from public.get_product_retention_calculation(p_organization_id,p_product_id,p_actor_user_id) t where t.outcome='found'; if retention is null then return query select 'invalid_request',null::jsonb; return; end if;
 payload:=jsonb_build_object('schemaVersion','m7_04_v1','capturedAt',public.m7_snapshot_timestamp_utc(clock_timestamp()),'technicalFile',technical_file,'readiness',readiness,'riskRegister',public.m7_risk_register_json(p_organization_id,p_product_id,true),'retention',retention); payload_text:=payload::text; digest:=encode(extensions.digest(payload_text,'sha256'),'hex'); if octet_length(payload_text)>5242880 then return query select 'invalid_request',null::jsonb; return; end if;
 insert into public.technical_file_snapshots(organization_id,technical_file_id,product_id,release_id,purpose,audit_rationale,technical_file_version,template_key,template_version,readiness_status,payload,payload_sha256,payload_byte_length,created_by) values(p_organization_id,f.id,p_product_id,p_release_id,p_purpose,case when p_purpose='audit' then btrim(p_audit_rationale) else null end,f.version,f.template_key,f.template_version,coalesce(readiness->>'overallStatus','empty'),payload,digest,octet_length(payload_text),p_actor_user_id) returning id into snapshot_id; insert into public.audit_logs(organization_id,user_id,action,entity_type,entity_id,changes) values(p_organization_id,p_actor_user_id,'technical_file.snapshot_created','technical_file_snapshot',snapshot_id::text,jsonb_build_object('snapshotId',snapshot_id,'idempotencyKey',p_idempotency_key,'payloadDigest',digest)); return query select 'created',public.m7_snapshot_json(p_organization_id,snapshot_id);
end $$;

revoke all on function public.m7_snapshot_json(uuid,uuid),public.m7_snapshot_export_json(uuid,uuid),public.m7_snapshot_timestamp_utc(timestamptz),public.create_technical_file_snapshot_atomic(uuid,uuid,uuid,integer,text,uuid,text,uuid) from public,anon,authenticated;
grant execute on function public.m7_snapshot_json(uuid,uuid),public.m7_snapshot_export_json(uuid,uuid),public.m7_snapshot_timestamp_utc(timestamptz),public.create_technical_file_snapshot_atomic(uuid,uuid,uuid,integer,text,uuid,text,uuid) to service_role;
alter function public.m7_snapshot_json(uuid,uuid) owner to postgres;
alter function public.m7_snapshot_export_json(uuid,uuid) owner to postgres;
alter function public.m7_snapshot_timestamp_utc(timestamptz) owner to postgres;
alter function public.create_technical_file_snapshot_atomic(uuid,uuid,uuid,integer,text,uuid,text,uuid) owner to postgres;
notify pgrst, 'reload schema';
